USE DATABASE OBS;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_AI_001
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-AI-001 Cortex credits by function and agent: Cortex token credits per day by function and agent (DIMENSION = function / agent; (no agent) when direct).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "TOKENS",
  "CALLS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    FUNCTION_NAME || ' / ' || AGENT_NAME AS DIMENSION,
    SUM(TOKEN_CREDITS) AS VALUE,
    SUM(TOKENS) AS TOKENS,
    COUNT(*) AS CALLS
  FROM CURATED.FACT_CORTEX_USAGE
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_AI_003
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-AI-003 Cortex tokens by model: Tokens processed per model and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    COALESCE(MODEL_NAME, '(unknown)') AS DIMENSION,
    SUM(TOKENS) AS VALUE
  FROM CURATED.FACT_CORTEX_USAGE
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_AI_004
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-AI-004 Cortex spend without agent identity: Share of Cortex credits not attributable to a governed agent (direct calls by personal users), per day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    SUM(CASE WHEN NO_AGENT THEN TOKEN_CREDITS ELSE 0 END) / SUM(TOKEN_CREDITS) AS VALUE
  FROM CURATED.FACT_CORTEX_USAGE
  GROUP BY
    1,
    2
  HAVING
    SUM(TOKEN_CREDITS) > 0
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_AI_005
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-AI-005 Cortex call latency: Average seconds per Cortex call, per function and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    FUNCTION_NAME AS DIMENSION,
    AVG(DATEDIFF(SECOND, START_TIME, END_TIME)) AS VALUE
  FROM CURATED.FACT_CORTEX_USAGE
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_AI_006
  TARGET_LAG = '168 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-AI-006 Semantic views: Number of semantic views in the account, per snapshot day (AI readiness of top KPI domains).'
AS
