  FROM CURATED.SNAPSHOT_HARVEST AS h
  LEFT JOIN CURATED.SNAP_SEMANTIC_VIEWS AS s
    ON s.ACCOUNT_NAME = h.ACCOUNT_NAME AND s.SNAPSHOT_DATE = h.SNAPSHOT_DATE
