CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_001
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-001 Credits by account, warehouse and day: Credits billed per warehouse and day: compute + cloud services credits from WAREHOUSE_METERING_HISTORY, with the account-day cloud-services adjustment from METERING_DAILY_HISTORY allocated pro rata to cloud-services use.'
AS
SELECT
