CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_002
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-002 Spend ($) by warehouse and day: KPI-COST-001 credits billed multiplied by the contract price per credit (client input).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "CREDITS_BILLED",
  "PRICE_PER_CREDIT"
FROM (
  SELECT
    d.ACCOUNT_NAME,
    d.DAY AS PERIOD,
    d.WAREHOUSE_NAME AS DIMENSION,
    d.CREDITS_BILLED * a.PRICE_PER_CREDIT AS VALUE,
    d.CREDITS_BILLED,
    a.PRICE_PER_CREDIT
  FROM CURATED.FACT_WAREHOUSE_DAILY AS d
  JOIN CURATED.DIM_ACCOUNT AS a
    ON a.ACCOUNT_NAME = d.ACCOUNT_NAME
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_003
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-003 Cost by cost centre: Daily billed cost ($) by cost centre: warehouse spend by the warehouses cost-centre tag; serverless, AI and untagged warehouse spend fall into UNALLOCATED. Sums to total billed spend (KPI-COST-011).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "CREDITS_BILLED"
FROM (
  WITH c AS (
    SELECT
      ACCOUNT_NAME,
      DAY,
      COALESCE(COST_CENTRE, 'UNALLOCATED') AS COST_CENTRE,
      CREDITS_BILLED
    FROM CURATED.FACT_WAREHOUSE_DAILY
    UNION ALL
    SELECT
      ACCOUNT_NAME,
      DAY,
      'UNALLOCATED',
      CREDITS_BILLED
    FROM CURATED.FACT_METERING_DAILY
    WHERE
      SERVICE_TYPE <> 'WAREHOUSE_METERING'
  )
  SELECT
    c.ACCOUNT_NAME,
    c.DAY AS PERIOD,
    c.COST_CENTRE AS DIMENSION,
    SUM(c.CREDITS_BILLED) * MAX(a.PRICE_PER_CREDIT) AS VALUE,
    SUM(c.CREDITS_BILLED) AS CREDITS_BILLED
  FROM c
  JOIN CURATED.DIM_ACCOUNT AS a
    ON a.ACCOUNT_NAME = c.ACCOUNT_NAME
  GROUP BY
    c.ACCOUNT_NAME,
    c.DAY,
    c.COST_CENTRE
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_004
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-004 Month-on-month spend trend: Percent change in average daily billed spend versus the previous calendar month (average daily spend makes partial months comparable).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "MONTH_USD",
  "AVG_DAILY_USD",
  "PREV_AVG_DAILY_USD",
  "DAYS"
FROM (
  WITH m AS (
    SELECT
      f.ACCOUNT_NAME,
      CAST(DATE_TRUNC('MONTH', f.DAY) AS DATE) AS MONTH,
      SUM(f.CREDITS_BILLED) * MAX(a.PRICE_PER_CREDIT) AS MONTH_USD,
      COUNT(DISTINCT f.DAY) AS DAYS
    FROM CURATED.FACT_METERING_DAILY AS f
    JOIN CURATED.DIM_ACCOUNT AS a
      ON a.ACCOUNT_NAME = f.ACCOUNT_NAME
    GROUP BY
      1,
      2
  ), t AS (
    SELECT
      ACCOUNT_NAME,
      MONTH,
      MONTH_USD,
      DAYS,
      MONTH_USD / DAYS AS AVG_DAILY_USD,
      LAG(MONTH_USD / DAYS) OVER (PARTITION BY ACCOUNT_NAME ORDER BY MONTH) AS PREV_AVG_DAILY_USD
    FROM m
  )
  SELECT
    ACCOUNT_NAME,
    MONTH AS PERIOD,
    '' AS DIMENSION,
    CASE
      WHEN PREV_AVG_DAILY_USD > 0
      THEN (
        AVG_DAILY_USD / PREV_AVG_DAILY_USD - 1
      ) * 100
    END AS VALUE,
    MONTH_USD,
    AVG_DAILY_USD,
    PREV_AVG_DAILY_USD,
    DAYS
  FROM t
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_005
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-005 Forecast vs budget: Month-end forecast of billed credits (month-to-date run rate x days in month) divided by the account budgets monthly spending limit (credits). Above 1.0 the month is forecast to overrun.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "MTD_CREDITS",
  "FORECAST_CREDITS",
  "BUDGET_CREDITS",
  "DAYS_ELAPSED",
  "DAYS_IN_MONTH"
FROM (
  WITH m AS (
    SELECT
      ACCOUNT_NAME,
      CAST(DATE_TRUNC('MONTH', DAY) AS DATE) AS MONTH,
      SUM(CREDITS_BILLED) AS MTD_CREDITS,
      MAX(DAY) AS LAST_DAY_SEEN
    FROM CURATED.FACT_METERING_DAILY
    GROUP BY
      1,
      2
  ), b AS (
    SELECT
      ACCOUNT_NAME,
      SUM(SPENDING_LIMIT) AS BUDGET_CREDITS
    FROM CURATED.SNAP_BUDGETS
    WHERE
      IS_LATEST AND SCOPE = 'ACCOUNT'
    GROUP BY
      1
  )
  SELECT
    m.ACCOUNT_NAME,
    m.MONTH AS PERIOD,
    '' AS DIMENSION,
    CASE
      WHEN b.BUDGET_CREDITS > 0
      THEN (
        m.MTD_CREDITS / (
          DATEDIFF(DAY, m.MONTH, m.LAST_DAY_SEEN) + 1
        ) * DAYOFMONTH(LAST_DAY(m.MONTH))
      ) / b.BUDGET_CREDITS
    END AS VALUE,
    m.MTD_CREDITS,
    m.MTD_CREDITS / (
      DATEDIFF(DAY, m.MONTH, m.LAST_DAY_SEEN) + 1
    ) * DAYOFMONTH(LAST_DAY(m.MONTH)) AS FORECAST_CREDITS,
    b.BUDGET_CREDITS,
    DATEDIFF(DAY, m.MONTH, m.LAST_DAY_SEEN) + 1 AS DAYS_ELAPSED,
    DAYOFMONTH(LAST_DAY(m.MONTH)) AS DAYS_IN_MONTH
  FROM m
  LEFT JOIN b
    ON b.ACCOUNT_NAME = m.ACCOUNT_NAME
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_006
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-006 Cost per query signature: Compute credits attributed to each parameterised query signature per day, in dollars.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "CREDITS",
  "EXECUTIONS",
  "USD_PER_EXECUTION"
FROM (
  SELECT
    q.ACCOUNT_NAME,
    q.DAY AS PERIOD,
    q.SIGNATURE AS DIMENSION,
    SUM(q.CREDITS_ATTRIBUTED_COMPUTE) * MAX(a.PRICE_PER_CREDIT) AS VALUE,
    SUM(q.CREDITS_ATTRIBUTED_COMPUTE) AS CREDITS,
    COUNT(*) AS EXECUTIONS,
    SUM(q.CREDITS_ATTRIBUTED_COMPUTE) * MAX(a.PRICE_PER_CREDIT) / COUNT(*) AS USD_PER_EXECUTION
  FROM CURATED.FACT_QUERY AS q
  JOIN CURATED.DIM_ACCOUNT AS a
    ON a.ACCOUNT_NAME = q.ACCOUNT_NAME
  GROUP BY
    q.ACCOUNT_NAME,
    q.DAY,
    q.SIGNATURE
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_007
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-007 Idle credit share: compute credits billed while the warehouse had no running queries / total compute credits'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
