CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_009
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-009 Storage by type: Average stored terabytes per day by storage type (database, stage, fail-safe, hybrid).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    'DATABASE' AS DIMENSION,
    STORAGE_BYTES / POWER(1024, 4) AS VALUE
  FROM CURATED.FACT_STORAGE_DAILY
  UNION ALL
  SELECT
    ACCOUNT_NAME,
    DAY,
    'STAGE',
    STAGE_BYTES / POWER(1024, 4)
  FROM CURATED.FACT_STORAGE_DAILY
  UNION ALL
  SELECT
    ACCOUNT_NAME,
    DAY,
    'FAILSAFE',
    FAILSAFE_BYTES / POWER(1024, 4)
  FROM CURATED.FACT_STORAGE_DAILY
  UNION ALL
  SELECT
    ACCOUNT_NAME,
    DAY,
    'HYBRID',
    HYBRID_TABLE_STORAGE_BYTES / POWER(1024, 4)
  FROM CURATED.FACT_STORAGE_DAILY
) AS k;

