CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_011
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-011 Total spend ($) by account and day: All billed credits (every service type) for the account-day multiplied by the contract price.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "CREDITS_BILLED"
FROM (
  SELECT
    f.ACCOUNT_NAME,
    f.DAY AS PERIOD,
    '' AS DIMENSION,
    SUM(f.CREDITS_BILLED) * MAX(a.PRICE_PER_CREDIT) AS VALUE,
    SUM(f.CREDITS_BILLED) AS CREDITS_BILLED
  FROM CURATED.FACT_METERING_DAILY AS f
  JOIN CURATED.DIM_ACCOUNT AS a
    ON a.ACCOUNT_NAME = f.ACCOUNT_NAME
  GROUP BY
