CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_012
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-012 Storage cost per month: Average stored TB (database + stage + fail-safe + hybrid) in the month x contract storage price per TB-month.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "AVG_TB"
FROM (
  SELECT
    s.ACCOUNT_NAME,
    CAST(DATE_TRUNC('MONTH', s.DAY) AS DATE) AS PERIOD,
    '' AS DIMENSION,
    AVG(
      (
        s.STORAGE_BYTES + s.STAGE_BYTES + s.FAILSAFE_BYTES + COALESCE(s.HYBRID_TABLE_STORAGE_BYTES, 0)
      ) / POWER(1024, 4)
    ) * MAX(a.STORAGE_PRICE_PER_TB_MONTH) AS VALUE,
    AVG(
      (
        s.STORAGE_BYTES + s.STAGE_BYTES + s.FAILSAFE_BYTES + COALESCE(s.HYBRID_TABLE_STORAGE_BYTES, 0)
      ) / POWER(1024, 4)
    ) AS AVG_TB
  FROM CURATED.FACT_STORAGE_DAILY AS s
  JOIN CURATED.DIM_ACCOUNT AS a
    ON a.ACCOUNT_NAME = s.ACCOUNT_NAME
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_013
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-013 Capacity commitment burn-down: Cumulative billed credits since the commitment start / annual committed credits, per day; compare with EXPECTED_SHARE (elapsed share of the commitment term).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "CONSUMED_CREDITS",
  "ANNUAL_COMMIT_CREDITS",
  "EXPECTED_SHARE"
FROM (
  WITH d AS (
    SELECT
      ACCOUNT_NAME,
      DAY,
      SUM(CREDITS_BILLED) AS CREDITS
    FROM CURATED.FACT_METERING_DAILY
    GROUP BY
      1,
      2
  )
  SELECT
    d.ACCOUNT_NAME,
    d.DAY AS PERIOD,
    '' AS DIMENSION,
    SUM(d.CREDITS) OVER (PARTITION BY d.ACCOUNT_NAME ORDER BY d.DAY) / a.ANNUAL_COMMIT_CREDITS AS VALUE,
    SUM(d.CREDITS) OVER (PARTITION BY d.ACCOUNT_NAME ORDER BY d.DAY) AS CONSUMED_CREDITS,
    a.ANNUAL_COMMIT_CREDITS,
    (
      DATEDIFF(DAY, a.COMMIT_START, d.DAY) + 1
    ) / (
      DATEDIFF(DAY, a.COMMIT_START, a.COMMIT_END) + 1
    ) AS EXPECTED_SHARE
  FROM d
  JOIN CURATED.DIM_ACCOUNT AS a
    ON a.ACCOUNT_NAME = d.ACCOUNT_NAME
  WHERE
    a.ANNUAL_COMMIT_CREDITS > 0 AND d.DAY >= a.COMMIT_START
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_015
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-015 Cloud services ratio: Cloud-services credits used / compute credits used for warehouse metering, per account and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    CASE
      WHEN CREDITS_USED_COMPUTE > 0
      THEN CREDITS_USED_CLOUD_SERVICES / CREDITS_USED_COMPUTE
    END AS VALUE
  FROM CURATED.FACT_METERING_DAILY
  WHERE
    SERVICE_TYPE = 'WAREHOUSE_METERING'
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_COST_020
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-COST-020 Resource monitor coverage: Share of warehouses with a resource monitor attached, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN NOT RESOURCE_MONITOR IS NULL THEN 1.0 ELSE 0.0 END) AS VALUE
  FROM CURATED.SNAP_WAREHOUSES
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_001
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-001 Tag coverage: Share of tables carrying at least one object-level tag, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "TABLES",
  "TAGGED"
FROM (
  SELECT
    t.ACCOUNT_NAME,
    t.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN NOT g.OBJECT_NAME IS NULL THEN 1.0 ELSE 0.0 END) AS VALUE,
    COUNT(*) AS TABLES,
    COUNT(g.OBJECT_NAME) AS TAGGED
  FROM CURATED.SNAP_TABLES AS t
  LEFT JOIN (
    SELECT DISTINCT
      ACCOUNT_NAME,
      SNAPSHOT_DATE,
      OBJECT_DATABASE,
      OBJECT_SCHEMA,
      OBJECT_NAME
    FROM CURATED.SNAP_TAG_REFERENCES
    WHERE
      DOMAIN = 'TABLE'
  ) AS g
    ON g.ACCOUNT_NAME = t.ACCOUNT_NAME
    AND g.SNAPSHOT_DATE = t.SNAPSHOT_DATE
    AND g.OBJECT_DATABASE = t.TABLE_CATALOG
    AND g.OBJECT_SCHEMA = t.TABLE_SCHEMA
    AND g.OBJECT_NAME = t.TABLE_NAME
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_002
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-002 Owner coverage on Tier-1 objects: Share of Tier-1 tables (TIER tag = tier1) carrying the owner tag, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "TIER1_TABLES",
  "OWNED"
FROM (
  WITH tags AS (
    SELECT
      ACCOUNT_NAME,
      SNAPSHOT_DATE,
      OBJECT_DATABASE || '.' || OBJECT_SCHEMA || '.' || OBJECT_NAME AS FQ,
      TAG_NAME,
      TAG_VALUE
    FROM CURATED.SNAP_TAG_REFERENCES
    WHERE
      DOMAIN = 'TABLE'
  ), tier1 AS (
    SELECT DISTINCT
      ACCOUNT_NAME,
      SNAPSHOT_DATE,
      FQ
    FROM tags
    WHERE
      TAG_NAME = 'TIER' AND TAG_VALUE = 'tier1'
  ), owned AS (
    SELECT DISTINCT
      t.ACCOUNT_NAME,
      t.SNAPSHOT_DATE,
      t.FQ
    FROM tags AS t
    LEFT JOIN CURATED.DIM_ACCOUNT AS a
      ON a.ACCOUNT_NAME = t.ACCOUNT_NAME
    WHERE
      t.TAG_NAME = COALESCE(a.OWNER_TAG, 'DATA_OWNER')
  )
  SELECT
    tier1.ACCOUNT_NAME,
    tier1.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN NOT owned.FQ IS NULL THEN 1.0 ELSE 0.0 END) AS VALUE,
    COUNT(*) AS TIER1_TABLES,
    COUNT(owned.FQ) AS OWNED
  FROM tier1
  LEFT JOIN owned
    ON owned.ACCOUNT_NAME = tier1.ACCOUNT_NAME
    AND owned.SNAPSHOT_DATE = tier1.SNAPSHOT_DATE
    AND owned.FQ = tier1.FQ
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_003
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-003 Masking coverage on classified columns: Share of PII-tagged columns with an active masking policy, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "CLASSIFIED_COLUMNS",
  "MASKED"
FROM (
  SELECT
    c.ACCOUNT_NAME,
    c.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN NOT p.REF_COLUMN_NAME IS NULL THEN 1.0 ELSE 0.0 END) AS VALUE,
    COUNT(*) AS CLASSIFIED_COLUMNS,
    COUNT(p.REF_COLUMN_NAME) AS MASKED
  FROM CURATED.SNAP_TAG_REFERENCES AS c
  LEFT JOIN (
    SELECT DISTINCT
      ACCOUNT_NAME,
      SNAPSHOT_DATE,
      REF_DATABASE_NAME,
      REF_SCHEMA_NAME,
      REF_ENTITY_NAME,
      REF_COLUMN_NAME
    FROM CURATED.SNAP_POLICY_REFERENCES
    WHERE
      POLICY_KIND = 'MASKING_POLICY' AND POLICY_STATUS = 'ACTIVE'
  ) AS p
    ON p.ACCOUNT_NAME = c.ACCOUNT_NAME
    AND p.SNAPSHOT_DATE = c.SNAPSHOT_DATE
    AND p.REF_DATABASE_NAME = c.OBJECT_DATABASE
    AND p.REF_SCHEMA_NAME = c.OBJECT_SCHEMA
    AND p.REF_ENTITY_NAME = c.OBJECT_NAME
    AND p.REF_COLUMN_NAME = c.COLUMN_NAME
  WHERE
    c.DOMAIN = 'COLUMN' AND c.TAG_NAME = 'PII'
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_004
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-004 DMF coverage on Tier-1 tables: Share of Tier-1 tables with at least one data metric function attached, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "TIER1_TABLES",
  "MONITORED"
FROM (
  WITH tier1 AS (
    SELECT DISTINCT
      ACCOUNT_NAME,
      SNAPSHOT_DATE,
      OBJECT_DATABASE || '.' || OBJECT_SCHEMA || '.' || OBJECT_NAME AS FQ
    FROM CURATED.SNAP_TAG_REFERENCES
    WHERE
      DOMAIN = 'TABLE' AND TAG_NAME = 'TIER' AND TAG_VALUE = 'tier1'
  ), dmf AS (
    SELECT DISTINCT
      ACCOUNT_NAME,
      SNAPSHOT_DATE,
      REF_ENTITY_NAME AS FQ
    FROM CURATED.SNAP_DATA_METRIC_FUNCTION_REFERENCES
  )
  SELECT
    tier1.ACCOUNT_NAME,
    tier1.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN NOT dmf.FQ IS NULL THEN 1.0 ELSE 0.0 END) AS VALUE,
    COUNT(*) AS TIER1_TABLES,
    COUNT(dmf.FQ) AS MONITORED
  FROM tier1
  LEFT JOIN dmf
    ON dmf.ACCOUNT_NAME = tier1.ACCOUNT_NAME
    AND dmf.SNAPSHOT_DATE = tier1.SNAPSHOT_DATE
    AND dmf.FQ = tier1.FQ
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_005
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-005 Data quality expectation violations: Number of data metric function results that violated their expectation, per account and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "MEASUREMENTS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    COUNT_IF(EXPECTATION_VIOLATED) AS VALUE,
    COUNT(*) AS MEASUREMENTS
  FROM CURATED.FACT_DQ_RESULT
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_006
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-006 Tier-1 column comment coverage: Share of columns on Tier-1 tables with a comment, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  WITH tier1 AS (
    SELECT DISTINCT
      ACCOUNT_NAME,
      SNAPSHOT_DATE,
      OBJECT_DATABASE || '.' || OBJECT_SCHEMA || '.' || OBJECT_NAME AS FQ
    FROM CURATED.SNAP_TAG_REFERENCES
    WHERE
      DOMAIN = 'TABLE' AND TAG_NAME = 'TIER' AND TAG_VALUE = 'tier1'
  )
  SELECT
    c.ACCOUNT_NAME,
    c.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN NOT c.COMMENT IS NULL THEN 1.0 ELSE 0.0 END) AS VALUE
  FROM CURATED.SNAP_COLUMNS AS c
  JOIN tier1
    ON tier1.ACCOUNT_NAME = c.ACCOUNT_NAME
    AND tier1.SNAPSHOT_DATE = c.SNAPSHOT_DATE
    AND tier1.FQ = c.FQ_NAME
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_007
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-007 Table comment coverage: Share of tables with a table-level comment, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN NOT COMMENT IS NULL THEN 1.0 ELSE 0.0 END) AS VALUE
  FROM CURATED.SNAP_TABLES
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_008
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-008 DMF pass rate: Share of data metric function results that met their expectation, per account and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN EXPECTATION_VIOLATED THEN 0.0 ELSE 1.0 END) AS VALUE
  FROM CURATED.FACT_DQ_RESULT
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_GOV_010
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-GOV-010 Classified columns: Number of columns carrying a PII classification tag, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    h.ACCOUNT_NAME,
    h.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    COUNT(c.COLUMN_NAME) AS VALUE
  FROM CURATED.SNAPSHOT_HARVEST AS h
  LEFT JOIN CURATED.SNAP_TAG_REFERENCES AS c
    ON c.ACCOUNT_NAME = h.ACCOUNT_NAME
    AND c.SNAPSHOT_DATE = h.SNAPSHOT_DATE
    AND c.DOMAIN = 'COLUMN'
    AND c.TAG_NAME = 'PII'
  WHERE
    h.SOURCE_TABLE = 'TAG_REFERENCES'
  GROUP BY
    1,
    2
) AS k;

-- KPI-PHI-001 is computed by altitude.observability.kpi (engine: python) or fed by the
-- Package D scorecard re-run; the table is loaded, not a dynamic table.
CREATE TABLE IF NOT EXISTS OBS.KPI.KPI_PHI_001 (
  ACCOUNT_NAME VARCHAR,
  PERIOD DATE,
  DIMENSION VARCHAR,
  VALUE FLOAT,
  PILLARS NUMBER(38,0)
) COMMENT = 'KPI-PHI-001 Platform Health Index: 0-100 index: rubric-weighted mean of WAF pillar scores, each the mean attainment of that pillars targeted KPIs (KPI monthly value vs its rubric target, capped at 1).';

-- KPI-PHI-002 is computed by altitude.observability.kpi (engine: python) or fed by the
-- Package D scorecard re-run; the table is loaded, not a dynamic table.
CREATE TABLE IF NOT EXISTS OBS.KPI.KPI_PHI_002 (
  ACCOUNT_NAME VARCHAR,
  PERIOD DATE,
  DIMENSION VARCHAR,
  VALUE FLOAT,
  KPIS NUMBER(38,0)
) COMMENT = 'KPI-PHI-002 Health Index by WAF pillar: Pillar scores (0-100) behind KPI-PHI-001, one per Well-Architected pillar and month.';

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_001
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-001 Query time p50 / p95 by warehouse: Median and 95th-percentile total elapsed time (ms) of successful queries per warehouse and day; VALUE is p95.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "P50_MS",
  "P95_MS",
  "QUERIES"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    WAREHOUSE_NAME AS DIMENSION,
    PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY
      TOTAL_ELAPSED_TIME) AS VALUE,
    PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY
      TOTAL_ELAPSED_TIME) AS P50_MS,
    PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY
      TOTAL_ELAPSED_TIME) AS P95_MS,
    COUNT(*) AS QUERIES
  FROM CURATED.FACT_QUERY
  WHERE
    NOT WAREHOUSE_NAME IS NULL AND EXECUTION_STATUS = 'SUCCESS'
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_002
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-002 Queued time by warehouse: Total seconds queries spent queued for warehouse overload per warehouse and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "QUEUED_QUERIES",
  "P95_QUEUED_MS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    WAREHOUSE_NAME AS DIMENSION,
    SUM(QUEUED_OVERLOAD_TIME) / 1000.0 AS VALUE,
    COUNT_IF(QUEUED_OVERLOAD_TIME > 0) AS QUEUED_QUERIES,
    PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY
      QUEUED_OVERLOAD_TIME) AS P95_QUEUED_MS
  FROM CURATED.FACT_QUERY
  WHERE
    NOT WAREHOUSE_NAME IS NULL
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_003
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-003 Spill to storage: Gigabytes spilled to local plus remote storage per warehouse and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "LOCAL_GB",
  "REMOTE_GB",
  "SPILLING_QUERIES"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    WAREHOUSE_NAME AS DIMENSION,
    (
      SUM(BYTES_SPILLED_TO_LOCAL_STORAGE) + SUM(BYTES_SPILLED_TO_REMOTE_STORAGE)
    ) / POWER(1024, 3) AS VALUE,
    SUM(BYTES_SPILLED_TO_LOCAL_STORAGE) / POWER(1024, 3) AS LOCAL_GB,
    SUM(BYTES_SPILLED_TO_REMOTE_STORAGE) / POWER(1024, 3) AS REMOTE_GB,
    COUNT_IF(BYTES_SPILLED_TO_LOCAL_STORAGE + BYTES_SPILLED_TO_REMOTE_STORAGE > 0) AS SPILLING_QUERIES
  FROM CURATED.FACT_QUERY
  WHERE
    NOT WAREHOUSE_NAME IS NULL
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_004
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-004 Pruning efficiency: 1 - partitions scanned / partitions total, over queries that touched partitioned tables, per warehouse and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "PARTITIONS_SCANNED",
  "PARTITIONS_TOTAL"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    WAREHOUSE_NAME AS DIMENSION,
    1 - SUM(PARTITIONS_SCANNED) / SUM(PARTITIONS_TOTAL) AS VALUE,
    SUM(PARTITIONS_SCANNED) AS PARTITIONS_SCANNED,
    SUM(PARTITIONS_TOTAL) AS PARTITIONS_TOTAL
  FROM CURATED.FACT_QUERY
  WHERE
    NOT WAREHOUSE_NAME IS NULL AND PARTITIONS_TOTAL > 0
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_005
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-005 Cache hit rate: Average share of scanned data served from the warehouse cache (PERCENTAGE_SCANNED_FROM_CACHE) per warehouse and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    WAREHOUSE_NAME AS DIMENSION,
    AVG(COALESCE(PERCENTAGE_SCANNED_FROM_CACHE, 0)) AS VALUE
  FROM CURATED.FACT_QUERY
  WHERE
    NOT WAREHOUSE_NAME IS NULL AND QUERY_TYPE = 'SELECT'
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_006
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-006 Compilation time p95: 95th-percentile compilation time (ms) per warehouse and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    WAREHOUSE_NAME AS DIMENSION,
    PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY
      COMPILATION_TIME) AS VALUE
  FROM CURATED.FACT_QUERY
  WHERE
    NOT WAREHOUSE_NAME IS NULL
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_007
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-007 Execution time per query signature: Average execution time (ms) per parameterised query signature and day — the series the regression alert compares against its forecast band.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "EXECUTIONS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    SIGNATURE AS DIMENSION,
    AVG(EXECUTION_TIME) AS VALUE,
    COUNT(*) AS EXECUTIONS
  FROM CURATED.FACT_QUERY
  WHERE
    EXECUTION_STATUS = 'SUCCESS' AND SIGNATURE <> '(none)'
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_008
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-008 Warehouse load (average running): Average number of running queries per active hour, per warehouse and day (WAREHOUSE_LOAD_HISTORY).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "AVG_QUEUED_LOAD"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    WAREHOUSE_NAME AS DIMENSION,
    AVG_RUNNING AS VALUE,
    AVG_QUEUED_LOAD
  FROM CURATED.FACT_WAREHOUSE_DAILY
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_009
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-009 Failed query rate: Share of queries that did not succeed, per warehouse and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    COALESCE(WAREHOUSE_NAME, '(serverless)') AS DIMENSION,
    AVG(CASE WHEN EXECUTION_STATUS = 'SUCCESS' THEN 0.0 ELSE 1.0 END) AS VALUE
  FROM CURATED.FACT_QUERY
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_PERF_011
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-PERF-011 Long-running queries: Number of queries whose elapsed time exceeds the rubric long-query limit, per warehouse and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    WAREHOUSE_NAME AS DIMENSION,
    COUNT_IF(TOTAL_ELAPSED_TIME > 600 * 1000) AS VALUE
  FROM CURATED.FACT_QUERY
  WHERE
    NOT WAREHOUSE_NAME IS NULL
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_REL_001
  TARGET_LAG = '2 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-REL-001 Task success rate: Succeeded task runs / all task runs (failed and skipped runs count as unsuccessful) per account and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "RUNS",
  "SUCCEEDED",
  "FAILED",
  "SKIPPED"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN STATE = 'SUCCEEDED' THEN 1.0 ELSE 0.0 END) AS VALUE,
    COUNT(*) AS RUNS,
    COUNT_IF(STATE = 'SUCCEEDED') AS SUCCEEDED,
    COUNT_IF(STATE = 'FAILED') AS FAILED,
    COUNT_IF(STATE = 'SKIPPED') AS SKIPPED
  FROM CURATED.FACT_TASK_RUN
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_REL_002
  TARGET_LAG = '2 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-REL-002 Failed tasks (24h): Number of failed task runs per account and day; FAILED_TIER1 counts tasks loading Tier-1 tables.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "FAILED_TIER1",
  "FAILED_TASKS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    COUNT_IF(STATE = 'FAILED') AS VALUE,
    COUNT_IF(STATE = 'FAILED' AND IS_TIER1) AS FAILED_TIER1,
    COUNT(DISTINCT CASE WHEN STATE = 'FAILED' THEN FQ_NAME END) AS FAILED_TASKS
  FROM CURATED.FACT_TASK_RUN
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_REL_003
  TARGET_LAG = '2 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-REL-003 Freshness SLA attainment: 1 when the tables loading task succeeded before the clients daily deadline, else 0; averaged over a window it is the attainment rate.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "LOADED_AT",
  "DEADLINE_TS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    TABLE_NAME AS DIMENSION,
    CASE WHEN MET THEN 1.0 ELSE 0.0 END AS VALUE,
    LOADED_AT,
    DEADLINE_TS
  FROM CURATED.FACT_FRESHNESS
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_REL_004
  TARGET_LAG = '2 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-REL-004 Harvest success rate: Successful (or intentionally skipped) harvest steps / all harvest steps per account and day (Section 7.8 target ≥ 99%).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "STEPS",
  "FAILED_STEPS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN STATUS IN ('ok', 'skipped') THEN 1.0 ELSE 0.0 END) AS VALUE,
    COUNT(*) AS STEPS,
    COUNT_IF(STATUS = 'failed') AS FAILED_STEPS
  FROM CURATED.FACT_HARVEST
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_REL_005
  TARGET_LAG = '2 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-REL-005 File load error rate: Share of files loaded by COPY / Snowpipe with a status other than Loaded, per target table and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "FILES",
  "ROWS_LOADED"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    TABLE_NAME AS DIMENSION,
    AVG(CASE WHEN STATUS = 'Loaded' THEN 0.0 ELSE 1.0 END) AS VALUE,
    COUNT(*) AS FILES,
    SUM(ROW_COUNT) AS ROWS_LOADED
  FROM CURATED.FACT_COPY
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_REL_010
  TARGET_LAG = '2 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-REL-010 Task retries: Number of task runs that needed more than one attempt, per account and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    COUNT_IF(ATTEMPT_NUMBER > 1) AS VALUE
  FROM CURATED.FACT_TASK_RUN
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_REL_011
  TARGET_LAG = '168 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-REL-011 Replication / failover groups: Number of replication or failover groups configured, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    h.ACCOUNT_NAME,
    h.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    COUNT(r.NAME) AS VALUE
  FROM CURATED.SNAPSHOT_HARVEST AS h
  LEFT JOIN CURATED.SNAP_REPLICATION_GROUPS AS r
    ON r.ACCOUNT_NAME = h.ACCOUNT_NAME AND r.SNAPSHOT_DATE = h.SNAPSHOT_DATE
  WHERE
    h.SOURCE_TABLE = 'REPLICATION_GROUPS'
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_001
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-001 MFA coverage: Share of enabled human users protected by MFA: HAS_MFA, or SSO-only users without a password (MFA enforced by the identity provider).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "HUMANS",
  "COVERED"
FROM (
  SELECT
    ACCOUNT_NAME,
    SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    AVG(
      CASE
        WHEN HAS_MFA OR (
          NOT EXT_AUTHN_UID IS NULL AND NOT COALESCE(HAS_PASSWORD, FALSE)
        )
        THEN 1.0
        ELSE 0.0
      END
    ) AS VALUE,
    COUNT(*) AS HUMANS,
    COUNT_IF(HAS_MFA OR (
      NOT EXT_AUTHN_UID IS NULL AND NOT COALESCE(HAS_PASSWORD, FALSE)
    )) AS COVERED
  FROM CURATED.SNAP_USERS
  WHERE
    COALESCE(TYPE, 'PERSON') = 'PERSON' AND NOT COALESCE(DISABLED, FALSE)
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_002
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-002 ACCOUNTADMIN grantees: Number of users granted the ACCOUNTADMIN role, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    h.ACCOUNT_NAME,
    h.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    COUNT(DISTINCT g.GRANTEE_NAME) AS VALUE
  FROM CURATED.SNAPSHOT_HARVEST AS h
  LEFT JOIN CURATED.SNAP_GRANTS_TO_USERS AS g
    ON g.ACCOUNT_NAME = h.ACCOUNT_NAME
    AND g.SNAPSHOT_DATE = h.SNAPSHOT_DATE
    AND g.ROLE = 'ACCOUNTADMIN'
  WHERE
    h.SOURCE_TABLE = 'GRANTS_TO_USERS'
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_003
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-003 Failed logins: Number of failed login attempts per account and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "USERS_AFFECTED",
  "SOURCE_IPS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    COUNT_IF(NOT IS_SUCCESS) AS VALUE,
    COUNT(DISTINCT CASE WHEN NOT IS_SUCCESS THEN USER_NAME END) AS USERS_AFFECTED,
    COUNT(DISTINCT CASE WHEN NOT IS_SUCCESS THEN CLIENT_IP END) AS SOURCE_IPS
  FROM CURATED.FACT_LOGIN
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_004
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-004 Dormant users: Enabled human users with no successful login within the rubric dormancy window, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    COUNT_IF(
      LAST_SUCCESS_LOGIN IS NULL
      OR DATEDIFF(DAY, CAST(LAST_SUCCESS_LOGIN AS DATE), SNAPSHOT_DATE) > 90
    ) AS VALUE
  FROM CURATED.SNAP_USERS
  WHERE
    COALESCE(TYPE, 'PERSON') = 'PERSON' AND NOT COALESCE(DISABLED, FALSE)
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_005
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-005 Network-policy coverage: 1.0 when an account-level network policy is set; otherwise the share of users with a user-level network policy.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    u.ACCOUNT_NAME,
    u.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    CASE
      WHEN NOT MAX(a.NETWORK_POLICY) IS NULL
      THEN 1.0
      ELSE AVG(CASE WHEN NOT u.NETWORK_POLICY IS NULL THEN 1.0 ELSE 0.0 END)
    END AS VALUE
  FROM CURATED.SNAP_USERS AS u
  LEFT JOIN CURATED.SNAP_ACCOUNT_INFO AS a
    ON a.ACCOUNT_NAME = u.ACCOUNT_NAME AND a.SNAPSHOT_DATE = u.SNAPSHOT_DATE
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_006
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-006 Human users without MFA: Number of enabled human users not protected by MFA (complement of KPI-SEC-001), per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    COUNT_IF(
      NOT (
        COALESCE(HAS_MFA, FALSE)
        OR (
          NOT EXT_AUTHN_UID IS NULL AND NOT COALESCE(HAS_PASSWORD, FALSE)
        )
      )
    ) AS VALUE
  FROM CURATED.SNAP_USERS
  WHERE
    COALESCE(TYPE, 'PERSON') = 'PERSON' AND NOT COALESCE(DISABLED, FALSE)
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_007
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-007 ACCOUNTADMIN activity: Queries executed under the ACCOUNTADMIN role per account and day (USERS = distinct users).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "USERS"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    COUNT(*) AS VALUE,
    COUNT(DISTINCT USER_NAME) AS USERS
  FROM CURATED.FACT_QUERY
  WHERE
    ROLE_NAME = 'ACCOUNTADMIN'
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_008
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-008 Service users with passwords: Service (or legacy service) users that still authenticate with a password, per snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    h.ACCOUNT_NAME,
    h.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    COUNT(u.NAME) AS VALUE
  FROM CURATED.SNAPSHOT_HARVEST AS h
  LEFT JOIN CURATED.SNAP_USERS AS u
    ON u.ACCOUNT_NAME = h.ACCOUNT_NAME
    AND u.SNAPSHOT_DATE = h.SNAPSHOT_DATE
    AND u.TYPE IN ('SERVICE', 'LEGACY_SERVICE')
    AND COALESCE(u.HAS_PASSWORD, FALSE)
  WHERE
    h.SOURCE_TABLE = 'USERS'
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_010
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-010 Orphan roles: Non-system roles granted to no user and no role (current snapshot).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    r.ACCOUNT_NAME,
    MAX(h.SNAPSHOT_DATE) AS PERIOD,
    '' AS DIMENSION,
    COUNT_IF(NOT r.IS_SYSTEM AND r.USER_GRANTS = 0 AND r.ROLE_GRANTS = 0) AS VALUE
  FROM CURATED.DIM_ROLE AS r
  JOIN CURATED.SNAPSHOT_HARVEST AS h
    ON h.ACCOUNT_NAME = r.ACCOUNT_NAME AND h.IS_LATEST AND h.SOURCE_TABLE = 'ROLES'
  GROUP BY
    1
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_SEC_012
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-SEC-012 Failed login share: Failed login attempts / all login attempts per account and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    '' AS DIMENSION,
    AVG(CASE WHEN IS_SUCCESS THEN 0.0 ELSE 1.0 END) AS VALUE
  FROM CURATED.FACT_LOGIN
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_USE_001
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-USE-001 Active users: Distinct users who ran at least one query, per account and day (HUMAN_USERS excludes service users).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "HUMAN_USERS"
FROM (
  SELECT
    q.ACCOUNT_NAME,
    q.DAY AS PERIOD,
    '' AS DIMENSION,
    COUNT(DISTINCT q.USER_NAME) AS VALUE,
    COUNT(DISTINCT CASE WHEN COALESCE(u.IS_HUMAN, TRUE) THEN q.USER_NAME END) AS HUMAN_USERS
  FROM CURATED.FACT_QUERY AS q
  LEFT JOIN CURATED.DIM_USER AS u
    ON u.ACCOUNT_NAME = q.ACCOUNT_NAME AND u.USER_NAME = q.USER_NAME
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_USE_002
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-USE-002 Queries by client tool: Number of queries per client application (driver / tool) and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    CLIENT_APPLICATION AS DIMENSION,
    COUNT(*) AS VALUE
  FROM CURATED.FACT_QUERY
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_USE_003
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-USE-003 Unused objects: Tables with no recorded access within the rubric window before the snapshot day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "TABLES"
FROM (
  SELECT
    t.ACCOUNT_NAME,
    t.SNAPSHOT_DATE AS PERIOD,
    '' AS DIMENSION,
    COUNT_IF(
      a.LAST_ACCESSED IS NULL
      OR DATEDIFF(DAY, CAST(a.LAST_ACCESSED AS DATE), t.SNAPSHOT_DATE) > 90
    ) AS VALUE,
    COUNT(*) AS TABLES
  FROM CURATED.SNAP_TABLES AS t
  LEFT JOIN (
    SELECT
      s.ACCOUNT_NAME,
      s.SNAPSHOT_DATE,
      f.OBJECT_NAME,
      MAX(f.QUERY_START_TIME) AS LAST_ACCESSED
    FROM (
      SELECT DISTINCT
        ACCOUNT_NAME,
        SNAPSHOT_DATE
      FROM CURATED.SNAP_TABLES
    ) AS s
    JOIN CURATED.FACT_ACCESS AS f
      ON f.ACCOUNT_NAME = s.ACCOUNT_NAME AND f.DAY <= s.SNAPSHOT_DATE
    GROUP BY
      1,
      2,
      3
  ) AS a
    ON a.ACCOUNT_NAME = t.ACCOUNT_NAME
    AND a.SNAPSHOT_DATE = t.SNAPSHOT_DATE
    AND a.OBJECT_NAME = t.FQ_NAME
  GROUP BY
    1,
    2
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_USE_004
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-USE-004 Query volume by warehouse: Number of queries per warehouse and day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    COALESCE(WAREHOUSE_NAME, '(none)') AS DIMENSION,
    COUNT(*) AS VALUE
  FROM CURATED.FACT_QUERY
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_USE_005
  TARGET_LAG = '6 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-USE-005 Top consumers: Compute credits attributed to each user per day (top consumers).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "QUERIES"
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    USER_NAME AS DIMENSION,
    SUM(CREDITS_ATTRIBUTED_COMPUTE) AS VALUE,
    COUNT(*) AS QUERIES
  FROM CURATED.FACT_QUERY_ATTRIBUTION
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_USE_006
  TARGET_LAG = '24 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-USE-006 Adoption by domain: Distinct users reading objects in each database schema (data domain) per day.'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE
FROM (
  SELECT
    ACCOUNT_NAME,
    DAY AS PERIOD,
    SPLIT_PART(OBJECT_NAME, '.', 1) || '.' || SPLIT_PART(OBJECT_NAME, '.', 2) AS DIMENSION,
    COUNT(DISTINCT USER_NAME) AS VALUE
  FROM CURATED.FACT_ACCESS
  WHERE
    ACCESS_TYPE = 'READ'
  GROUP BY
    1,
    2,
    3
) AS k;

CREATE OR REPLACE DYNAMIC TABLE OBS.KPI.KPI_USE_007
  TARGET_LAG = '168 hours'
  WAREHOUSE = OBS_WH
  COMMENT = 'KPI-USE-007 BI report views (90 days): Views in the last 90 days per BI report, per snapshot day (BI metadata).'
AS
SELECT
  CAST(ACCOUNT_NAME AS VARCHAR) AS ACCOUNT_NAME,
  CAST(PERIOD AS DATE) AS PERIOD,
  COALESCE(CAST(DIMENSION AS VARCHAR), '') AS DIMENSION,
  CAST(VALUE AS DOUBLE) AS VALUE,
  "REFRESHES_PER_DAY"
FROM (
  SELECT
    ACCOUNT_NAME,
    SNAPSHOT_DATE AS PERIOD,
    REPORT_ID || ' ' || NAME AS DIMENSION,
    VIEWS_90D AS VALUE,
    REFRESHES_PER_DAY
  FROM CURATED.SNAP_BI_REPORTS
) AS k;
